class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return "..."

    def introduce(self):
        return f"{self.name}: {self.speak()}"


class Dog(Animal):
    def speak(self):
        return "멍멍"


class Cat(Animal):
    def speak(self):
        return "야옹"


kinds = {"dog": Dog, "cat": Cat}
n = int(input())
for _ in range(n):
    kind, name = input().split()
    animal = kinds[kind](name)
    print(animal.introduce())
